    static void checkToolCall(JsonNode d, String path) {
        if (!isObject(d)) throw new FrameException(path + " must be an object");
        if (!d.has("session_id")) throw new FrameException(path + ".session_id is required");
        if (!d.has("call_ref")) throw new FrameException(path + ".call_ref is required");
        if (!d.has("name")) throw new FrameException(path + ".name is required");
        if (d.has("session_id")) {
            if (stringOf(d.get("session_id")) == null) throw new FrameException(path + ".session_id" + " must be a string");
            if (!matches(stringOf(d.get("session_id")), "^vs_[A-Za-z0-9-]+\\z")) throw new FrameException(path + ".session_id" + " does not match ^vs_[A-Za-z0-9-]+$");
        }
        if (d.has("call_ref")) {
            if (stringOf(d.get("call_ref")) == null) throw new FrameException(path + ".call_ref" + " must be a string");
            if (stringOf(d.get("call_ref")).length() < 1) throw new FrameException(path + ".call_ref" + " is shorter than 1");
            if (stringOf(d.get("call_ref")).length() > 64) throw new FrameException(path + ".call_ref" + " is longer than 64");
        }
        if (d.has("name")) {
            if (stringOf(d.get("name")) == null) throw new FrameException(path + ".name" + " must be a string");
            if (!matches(stringOf(d.get("name")), "^[a-z][a-z0-9_]*\\z")) throw new FrameException(path + ".name" + " does not match ^[a-z][a-z0-9_]*$");
        }
        if (d.has("arguments")) {
            if (!isObject(d.get("arguments"))) throw new FrameException(path + ".arguments" + " must be an object");
        }
        if (Objects.equals(stringOf(d.get("name")), "transfer")) {
            if (!isObject(d)) throw new FrameException(path + " must be an object");
            if (!d.has("arguments")) throw new FrameException(path + ".arguments is required");
            if (d.has("arguments")) {
                if (!isObject(d.get("arguments"))) throw new FrameException(path + ".arguments" + " must be an object");
                if (!d.get("arguments").has("to")) throw new FrameException(path + ".arguments" + ".to is required");
                if (d.get("arguments").has("to")) {
                    checkParty(d.get("arguments").get("to"), path + ".arguments" + ".to");
                    if (!isObject(d.get("arguments").get("to"))) throw new FrameException(path + ".arguments" + ".to" + " must be an object");
                    if (d.get("arguments").get("to").has("kind")) {
                        if (!isOneOf(stringOf(d.get("arguments").get("to").get("kind")), "user", "number", "agent")) throw new FrameException(path + ".arguments" + ".to" + ".kind" + " is not one of the allowed values");
                    }
                }
            }
        } else if (Objects.equals(stringOf(d.get("name")), "hangup")) {
            if (!isObject(d)) throw new FrameException(path + " must be an object");
            if (d.has("arguments")) {
                if (!isObject(d.get("arguments"))) throw new FrameException(path + ".arguments" + " must be an object");
            }
        } else if (Objects.equals(stringOf(d.get("name")), "send_dtmf")) {
            if (!isObject(d)) throw new FrameException(path + " must be an object");
            if (!d.has("arguments")) throw new FrameException(path + ".arguments is required");
            if (d.has("arguments")) {
                if (!isObject(d.get("arguments"))) throw new FrameException(path + ".arguments" + " must be an object");
                if (!d.get("arguments").has("digits")) throw new FrameException(path + ".arguments" + ".digits is required");
                if (d.get("arguments").has("digits")) {
                    if (stringOf(d.get("arguments").get("digits")) == null) throw new FrameException(path + ".arguments" + ".digits" + " must be a string");
                    if (!matches(stringOf(d.get("arguments").get("digits")), "^[0-9*#A-Dw]+\\z")) throw new FrameException(path + ".arguments" + ".digits" + " does not match ^[0-9*#A-Dw]+$");
                }
            }
        } else if (Objects.equals(stringOf(d.get("name")), "hold")) {
            if (!isObject(d)) throw new FrameException(path + " must be an object");
            if (!d.has("arguments")) throw new FrameException(path + ".arguments is required");
            if (d.has("arguments")) {
                if (!isObject(d.get("arguments"))) throw new FrameException(path + ".arguments" + " must be an object");
                if (!d.get("arguments").has("held")) throw new FrameException(path + ".arguments" + ".held is required");
                if (d.get("arguments").has("held")) {
                    if (boolOf(d.get("arguments").get("held")) == null) throw new FrameException(path + ".arguments" + ".held" + " must be true or false");
                }
            }
        } else {
            if (!isObject(d)) throw new FrameException(path + " must be an object");
            if (d.has("arguments")) {
                if (!isObject(d.get("arguments"))) throw new FrameException(path + ".arguments" + " must be an object");
            }
        }
    }

